"""Turn microduck_rl's uv.lock into a pip requirements file for the ROCm venv.

uv.lock is a universal lock covering every platform. Walk the dependency graph
from the project root, follow only the edges whose markers hold on this
interpreter, and pin every reached registry package at its locked version.

Left out on purpose:
- CUDA-only packages (torch, triton, warp-lang, nvidia-*): torch and Warp come
  from ROCm builds, and their own dependencies are installed with them.
- git and editable sources (BAM, the project itself): setup_env.sh installs
  them separately.

With --pins, the [pip] versions recorded in pins.toml are checked against the
lock, so the documented versions cannot drift from what is installed.
"""

import argparse
import re
import sys
import tomllib

from packaging.markers import Marker

EXCLUDE = re.compile(r"^(torch|triton|warp-lang|nvidia-.*)$")


def marker_holds(marker: str | None, extras: frozenset[str] = frozenset()) -> bool:
    if not marker:
        return True
    m = Marker(marker)
    if not extras:
        return m.evaluate({"extra": ""})
    return any(m.evaluate({"extra": e}) for e in extras)


def pick(candidates: list[dict], dep: dict) -> dict:
    if "version" in dep:
        candidates = [p for p in candidates if p["version"] == dep["version"]]
    if len(candidates) > 1:
        candidates = [
            p for p in candidates
            if any(marker_holds(m) for m in p.get("resolution-markers", [""]))
        ]
    if len(candidates) != 1:
        raise SystemExit(f"cannot choose a single version of {dep['name']}: {candidates}")
    return candidates[0]


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("lock", help="path to uv.lock")
    ap.add_argument("-o", "--output", required=True)
    ap.add_argument("--pins", help="pins.toml whose [pip] versions must match the lock")
    args = ap.parse_args()

    with open(args.lock, "rb") as f:
        lock = tomllib.load(f)
    by_name: dict[str, list[dict]] = {}
    for p in lock["package"]:
        by_name.setdefault(p["name"], []).append(p)
    root = next(p for p in lock["package"] if p["source"].get("editable") == ".")

    reached: dict[str, dict] = {}
    queue = [(root, frozenset())]
    while queue:
        pkg, extras = queue.pop()
        edges = list(pkg.get("dependencies", []))
        for extra in extras:
            edges += pkg.get("optional-dependencies", {}).get(extra, [])
        for dep in edges:
            if EXCLUDE.match(dep["name"]) or not marker_holds(dep.get("marker")):
                continue
            target = pick(by_name[dep["name"]], dep)
            dep_extras = frozenset(dep.get("extra", []))
            seen = reached.get(target["name"])
            if seen is not None and dep_extras <= seen["extras"]:
                continue
            merged = dep_extras | (seen["extras"] if seen else frozenset())
            reached[target["name"]] = {"pkg": target, "extras": merged}
            queue.append((target, merged))

    lines = []
    for name in sorted(reached):
        pkg = reached[name]["pkg"]
        if "registry" in pkg["source"]:
            lines.append(f"{name}=={pkg['version']}")
    with open(args.output, "w") as f:
        f.write("# Generated by lock_to_requirements.py from microduck_rl's uv.lock.\n")
        f.write("# Installed with --no-deps; CUDA-only, git and editable packages excluded.\n")
        f.write("\n".join(lines) + "\n")
    print(f"{len(lines)} pinned packages -> {args.output}")

    if args.pins:
        with open(args.pins, "rb") as f:
            pins = tomllib.load(f).get("pip", {})
        def locked(pkg: dict, want: str) -> str:
            # A git pin ("git+<url>@<commit>") is compared by commit, everything else by version.
            if want.startswith("git+"):
                return pkg["source"].get("git", "").rpartition("#")[2]
            return pkg["version"]

        bad = []
        for name, want in pins.items():
            if not isinstance(want, str) or name not in reached:
                continue
            got = locked(reached[name]["pkg"], want)
            expected = want.rpartition("@")[2] if want.startswith("git+") else want
            if got != expected:
                bad.append(f"{name}: pins.toml {expected}, uv.lock {got}")
        if bad:
            sys.exit("pins.toml disagrees with uv.lock:\n  " + "\n  ".join(bad))


if __name__ == "__main__":
    main()
